WITH parsed AS (SELECT id, plan, effective_from, tier_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, COUNT_IF(plan = 'enterprise') AS enterprise_events, SIZE(COLLECT_SET(plan)) AS num_plans FROM parsed GROUP BY DATE_TRUNC('QUARTER', effective_from) HAVING enterprise_events >= 1 ORDER BY num_plans DESC;
